/* Stillwater line art. Every page is generated by code as an SVG string.
   All shapes are closed (circles, polygons, closed paths) and every page has
   a frame, so the fill bucket always finds a sealed area. */
(function () {
  var S = 1200, C = 600;
  var P = Math.PI;
  function f(n) { return Math.round(n * 10) / 10; }
  function wrap(body, sw) {
    return '<svg xmlns="http://www.w3.org/2000/svg" width="' + S + '" height="' + S + '" viewBox="0 0 ' + S + ' ' + S + '">' +
      '<g fill="none" stroke="#2b2b33" stroke-width="' + (sw || 4) + '" stroke-linejoin="round" stroke-linecap="round">' +
      '<rect x="14" y="14" width="1172" height="1172" rx="28"/>' + body + '</g></svg>';
  }
  function circle(x, y, r) { return '<circle cx="' + f(x) + '" cy="' + f(y) + '" r="' + f(r) + '"/>'; }
  function poly(pts) { return '<polygon points="' + pts.map(function (p) { return f(p[0]) + ',' + f(p[1]); }).join(' ') + '"/>'; }
  function path(d) { return '<path d="' + d + '"/>'; }
  function line(a, b, c, d) { return '<line x1="' + f(a) + '" y1="' + f(b) + '" x2="' + f(c) + '" y2="' + f(d) + '"/>'; }
  function pt(cx, cy, r, a) { return [cx + r * Math.cos(a), cy + r * Math.sin(a)]; }
  // petal: closed lens shape from inner radius r1 to outer radius r2 at angle a
  function petal(cx, cy, r1, r2, a, w) {
    var p1 = pt(cx, cy, r1, a), p2 = pt(cx, cy, r2, a);
    var m = (r1 + r2) / 2, c1 = pt(cx, cy, m, a - w), c2 = pt(cx, cy, m, a + w);
    return path('M' + f(p1[0]) + ' ' + f(p1[1]) + ' Q' + f(c1[0]) + ' ' + f(c1[1]) + ' ' + f(p2[0]) + ' ' + f(p2[1]) +
      ' Q' + f(c2[0]) + ' ' + f(c2[1]) + ' ' + f(p1[0]) + ' ' + f(p1[1]) + 'Z');
  }
  function ring(cx, cy, r1, r2, n, w, off) {
    var s = ''; for (var i = 0; i < n; i++) s += petal(cx, cy, r1, r2, (i + (off || 0)) * 2 * P / n, w); return s;
  }
  // leaf with a mid vein that splits it into two closed halves
  function leaf(x, y, len, ang, wid) {
    var tip = [x + len * Math.cos(ang), y + len * Math.sin(ang)];
    var m = [x + len / 2 * Math.cos(ang), y + len / 2 * Math.sin(ang)];
    var n = [-Math.sin(ang) * wid, Math.cos(ang) * wid];
    return path('M' + f(x) + ' ' + f(y) + ' Q' + f(m[0] + n[0]) + ' ' + f(m[1] + n[1]) + ' ' + f(tip[0]) + ' ' + f(tip[1]) +
      ' Q' + f(m[0] - n[0]) + ' ' + f(m[1] - n[1]) + ' ' + f(x) + ' ' + f(y) + 'Z') + line(x, y, tip[0], tip[1]);
  }
  function flower(x, y, r, n) {
    return ring(x, y, r * 0.25, r, n, 0.45) + circle(x, y, r * 0.28) + circle(x, y, r * 0.12);
  }

  var pages = [];

  // 1 Lotus Mandala
  (function () {
    var b = '';
    b += circle(C, C, 520) + circle(C, C, 470);
    b += ring(C, C, 330, 465, 24, 0.13);
    b += circle(C, C, 330);
    b += ring(C, C, 210, 325, 16, 0.2, 0.5);
    b += circle(C, C, 210);
    b += ring(C, C, 110, 205, 12, 0.28);
    b += circle(C, C, 110) + ring(C, C, 30, 105, 8, 0.4, 0.5) + circle(C, C, 30);
    for (var i = 0; i < 24; i++) { var p = pt(C, C, 495, (i + 0.5) * 2 * P / 24); b += circle(p[0], p[1], 14); }
    pages.push({ id: 'lotus-mandala', title: 'Lotus Mandala', theme: 'Mandala', svg: wrap(b) });
  })();

  // 2 Star Compass (geometric)
  (function () {
    var b = '';
    for (var k = 0; k < 3; k++) {
      var r = 500 - k * 150, pts = [];
      for (var i = 0; i < 32; i++) pts.push(pt(C, C, i % 2 ? r * 0.62 : r, i * P / 16 + k * P / 16));
      b += poly(pts);
    }
    b += circle(C, C, 120);
    var hx = []; for (var j = 0; j < 6; j++) hx.push(pt(C, C, 90, j * P / 3)); b += poly(hx);
    b += circle(C, C, 40);
    [[120, 120], [1080, 120], [120, 1080], [1080, 1080]].forEach(function (c) { b += circle(c[0], c[1], 70) + circle(c[0], c[1], 35); });
    pages.push({ id: 'star-compass', title: 'Star Compass', theme: 'Geometric', svg: wrap(b) });
  })();

  // 3 Quiet Forest
  (function () {
    var b = '';
    b += circle(900, 230, 90);
    b += path('M14 640 Q300 520 600 620 T1186 600 L1186 1186 L14 1186 Z');
    b += path('M14 820 Q400 740 700 830 T1186 800 L1186 1186 L14 1186 Z');
    var trees = [[180, 820, 300], [400, 860, 360], [640, 840, 280], [880, 870, 340], [1060, 840, 260]];
    trees.forEach(function (t) {
      var x = t[0], y = t[1], h = t[2];
      for (var i = 0; i < 3; i++) {
        var top = y - h + i * h * 0.25, bot = y - h * 0.45 + i * h * 0.28, w = h * (0.22 + i * 0.08);
        b += poly([[x, top], [x + w, bot], [x - w, bot]]);
      }
      b += poly([[x - 16, y + h * 0.12], [x + 16, y + h * 0.12], [x + 16, y + 60 + h * 0.1], [x - 16, y + 60 + h * 0.1]]);
    });
    [[150, 1080], [520, 1110], [950, 1090]].forEach(function (m) {
      b += path('M' + (m[0] - 50) + ' ' + m[1] + ' Q' + m[0] + ' ' + (m[1] - 80) + ' ' + (m[0] + 50) + ' ' + m[1] + ' Z');
      b += poly([[m[0] - 12, m[1]], [m[0] + 12, m[1]], [m[0] + 12, m[1] + 40], [m[0] - 12, m[1] + 40]]);
    });
    b += path('M200 200 q30 -25 60 0 q30 -25 60 0');
    b += path('M330 300 q25 -20 50 0 q25 -20 50 0');
    pages.push({ id: 'quiet-forest', title: 'Quiet Forest', theme: 'Nature', svg: wrap(b) });
  })();

  // 4 Ocean Drift
  (function () {
    var b = '';
    for (var w = 0; w < 5; w++) {
      var y = 300 + w * 180, d = 'M14 ' + y;
      for (var x = 14; x < 1186; x += 120) d += ' Q' + (x + 60) + ' ' + (y - 50 + (w % 2) * 20) + ' ' + Math.min(x + 120, 1186) + ' ' + y;
      b += path(d + ' L1186 1186 L14 1186 Z');
    }
    function fish(x, y, s, dir) {
      var k = dir;
      b += path('M' + x + ' ' + y + ' Q' + (x + 60 * s * k) + ' ' + (y - 40 * s) + ' ' + (x + 120 * s * k) + ' ' + y +
        ' Q' + (x + 60 * s * k) + ' ' + (y + 40 * s) + ' ' + x + ' ' + y + 'Z');
      b += poly([[x, y], [x - 40 * s * k, y - 30 * s], [x - 40 * s * k, y + 30 * s]]);
      b += circle(x + 95 * s * k, y - 6 * s, 7 * s);
    }
    fish(220, 430, 1.2, 1); fish(800, 600, 1.5, -1); fish(400, 790, 1, 1); fish(950, 960, 1.1, -1);
    // shell
    b += path('M600 1130 L480 1060 Q600 900 720 1060 Z');
    for (var i = 1; i < 5; i++) b += line(600, 1130, 480 + i * 48, 1060 - Math.sin(i / 5 * P) * 60);
    [[160, 1000, 26], [1050, 330, 20], [700, 240, 30], [300, 160, 18]].forEach(function (c) { b += circle(c[0], c[1], c[2]); });
    b += circle(980, 140, 80);
    pages.push({ id: 'ocean-drift', title: 'Ocean Drift', theme: 'Ocean', svg: wrap(b) });
  })();

  // 5 Wildflower Meadow
  (function () {
    var b = '';
    b += path('M14 900 Q600 820 1186 900 L1186 1186 L14 1186 Z');
    var fl = [[230, 420, 110, 8], [600, 330, 150, 12], [960, 450, 120, 10], [390, 700, 90, 6], [820, 720, 95, 7]];
    fl.forEach(function (q) {
      b += path('M' + (q[0] - 8) + ' ' + (q[1] + q[2]) + ' L' + (q[0] - 8) + ' 890 L' + (q[0] + 8) + ' 890 L' + (q[0] + 8) + ' ' + (q[1] + q[2]) + ' Z');
      b += leaf(q[0] + 8, q[1] + q[2] + 150, 110, -0.5, 30) + leaf(q[0] - 8, q[1] + q[2] + 230, 110, P + 0.5, 30);
      b += flower(q[0], q[1], q[2], q[3]);
    });
    for (var i = 0; i < 9; i++) b += circle(100 + i * 125, 1040 + (i % 2) * 60, 24);
    pages.push({ id: 'wildflower-meadow', title: 'Wildflower Meadow', theme: 'Floral', svg: wrap(b) });
  })();

  // 6 Botanical Leaves
  (function () {
    var b = '';
    b += circle(C, C, 90) + circle(C, C, 40);
    for (var i = 0; i < 10; i++) {
      var a = i * 2 * P / 10, s = pt(C, C, 95, a);
      b += leaf(s[0], s[1], 300, a, 80);
      var s2 = pt(C, C, 420, a + P / 10);
      b += leaf(s2[0], s2[1], 140, a + P / 10, 40);
    }
    [[120, 120], [1080, 120], [120, 1080], [1080, 1080]].forEach(function (c) { b += flower(c[0], c[1], 80, 6); });
    pages.push({ id: 'botanical-leaves', title: 'Botanical Leaves', theme: 'Botanical', svg: wrap(b) });
  })();

  // 7 Hex Garden (geometric honeycomb)
  (function () {
    var b = '', r = 80, h = Math.sqrt(3) * r;
    for (var row = -1; row < 10; row++) for (var col = -1; col < 9; col++) {
      var x = col * 1.5 * r + 60, y = row * h + (col % 2 ? h / 2 : 0) + 40;
      var pts = []; for (var k = 0; k < 6; k++) pts.push(pt(x, y, r, k * P / 3));
      b += poly(pts);
      if ((row + col) % 3 === 0) { var ip = []; for (var k2 = 0; k2 < 6; k2++) ip.push(pt(x, y, r * 0.5, k2 * P / 3 + P / 6)); b += poly(ip); }
    }
    b = '<clipPath id="cp"><rect x="14" y="14" width="1172" height="1172" rx="28"/></clipPath><g clip-path="url(#cp)">' + b + '</g>';
    pages.push({ id: 'hex-garden', title: 'Hex Garden', theme: 'Geometric', svg: wrap(b) });
  })();

  // 8 Moon Moth (symmetry)
  (function () {
    var b = '';
    b += path('M600 330 Q330 120 170 300 Q120 520 590 560 Z');
    b += path('M600 330 Q870 120 1030 300 Q1080 520 610 560 Z');
    b += path('M590 600 Q300 640 260 860 Q360 1000 595 700 Z');
    b += path('M610 600 Q900 640 940 860 Q840 1000 605 700 Z');
    b += circle(380, 380, 70) + circle(380, 380, 32) + circle(820, 380, 70) + circle(820, 380, 32);
    b += circle(420, 780, 50) + circle(780, 780, 50);
    b += path('M600 300 Q640 500 600 820 Q560 500 600 300 Z');
    b += path('M590 310 Q540 200 470 180'); b += path('M610 310 Q660 200 730 180');
    b += circle(470, 180, 12) + circle(730, 180, 12);
    for (var i = 0; i < 14; i++) { var p = pt(C, 1000, 140, P + i * P / 13); b += circle(p[0], p[1] + 60, 16); }
    b += circle(C, C, 560);
    pages.push({ id: 'moon-moth', title: 'Moon Moth', theme: 'Nature', svg: wrap(b) });
  })();

  // 9 Sun Rose Mandala
  (function () {
    var b = '';
    b += circle(C, C, 540);
    for (var i = 0; i < 36; i++) { var a = i * 2 * P / 36; b += poly([pt(C, C, 470, a - 0.07), pt(C, C, 540, a), pt(C, C, 470, a + 0.07)]); }
    b += circle(C, C, 470);
    b += ring(C, C, 300, 465, 18, 0.16) + ring(C, C, 300, 420, 18, 0.1, 0.5);
    b += circle(C, C, 300) + circle(C, C, 260);
    b += ring(C, C, 140, 255, 10, 0.3);
    b += circle(C, C, 140) + flower(C, C, 130, 8);
    pages.push({ id: 'sun-rose', title: 'Sun Rose', theme: 'Mandala', svg: wrap(b) });
  })();

  // 10 Mountain Lake
  (function () {
    var b = '';
    b += circle(860, 260, 100) + circle(860, 260, 70);
    b += poly([[14, 700], [260, 330], [420, 520], [600, 260], [820, 560], [980, 400], [1186, 700]]);
    b += poly([[260, 330], [320, 420], [280, 400], [230, 430], [210, 405]]);
    b += poly([[600, 260], [670, 360], [620, 340], [560, 380], [540, 350]]);
    b += path('M14 700 L1186 700 L1186 1186 L14 1186 Z');
    for (var i = 0; i < 6; i++) b += path('M' + (150 + i * 160) + ' ' + (780 + (i % 3) * 110) + ' q40 -14 80 0 q-40 14 -80 0 Z');
    b += path('M500 900 L700 900 L660 960 L540 960 Z') + line(600, 900, 600, 800) + poly([[604, 805], [680, 890], [604, 890]]);
    pages.push({ id: 'mountain-lake', title: 'Mountain Lake', theme: 'Nature', svg: wrap(b) });
  })();

  // 11 Koi Pond
  (function () {
    var b = '';
    b += circle(C, C, 540);
    function koi(x, y, a, s) {
      var c = Math.cos(a), sn = Math.sin(a);
      function T(px, py) { return f(x + (px * c - py * sn) * s) + ' ' + f(y + (px * sn + py * c) * s); }
      b += path('M' + T(-120, 0) + ' Q' + T(-40, -60) + ' ' + T(80, -30) + ' Q' + T(130, 0) + ' ' + T(80, 30) + ' Q' + T(-40, 60) + ' ' + T(-120, 0) + 'Z');
      b += path('M' + T(-120, 0) + ' L' + T(-190, -45) + ' Q' + T(-165, 0) + ' ' + T(-190, 45) + ' Z');
      b += path('M' + T(10, -38) + ' Q' + T(-20, -90) + ' ' + T(-60, -80) + ' Q' + T(-30, -50) + ' ' + T(-20, -45) + ' Z');
      b += path('M' + T(10, 38) + ' Q' + T(-20, 90) + ' ' + T(-60, 80) + ' Q' + T(-30, 50) + ' ' + T(-20, 45) + ' Z');
      b += path('M' + T(-40, -30) + ' Q' + T(0, 0) + ' ' + T(-40, 30) + ' Q' + T(-70, 0) + ' ' + T(-40, -30) + ' Z');
      b += circle(x + (85 * c + 12 * sn) * s, y + (85 * sn - 12 * c) * s, 7 * s);
    }
    koi(450, 430, 0.5, 1.3); koi(780, 760, P + 0.4, 1.3);
    [[860, 330, 110], [330, 830, 95]].forEach(function (l) {
      b += path('M' + l[0] + ' ' + l[1] + ' L' + (l[0] + l[2]) + ' ' + (l[1] - 20) + ' A' + l[2] + ' ' + l[2] + ' 0 1 1 ' + (l[0] + l[2]) + ' ' + (l[1] + 20) + ' Z');
      b += flower(l[0], l[1], 45, 8);
    });
    [[600, 600, 60], [600, 600, 30], [250, 300, 40], [950, 950, 35]].forEach(function (r) { b += circle(r[0], r[1], r[2]); });
    pages.push({ id: 'koi-pond', title: 'Koi Pond', theme: 'Ocean', svg: wrap(b) });
  })();

  // 12 Art Deco Fans
  (function () {
    var b = '';
    for (var row = 0; row < 6; row++) for (var col = 0; col < 7; col++) {
      var x = col * 200 + (row % 2 ? 100 : 0), y = row * 200 + 200, r = 200;
      b += path('M' + (x - r) + ' ' + y + ' A' + r + ' ' + r + ' 0 0 1 ' + (x + r) + ' ' + y + ' Z');
      b += path('M' + (x - r * 0.62) + ' ' + y + ' A' + (r * 0.62) + ' ' + (r * 0.62) + ' 0 0 1 ' + (x + r * 0.62) + ' ' + y + ' Z');
      b += path('M' + (x - r * 0.25) + ' ' + y + ' A' + (r * 0.25) + ' ' + (r * 0.25) + ' 0 0 1 ' + (x + r * 0.25) + ' ' + y + ' Z');
      for (var k = 1; k < 6; k++) { var a = P + k * P / 6, p1 = pt(x, y, r * 0.62, a), p2 = pt(x, y, r, a); b += line(p1[0], p1[1], p2[0], p2[1]); }
    }
    b = '<clipPath id="cpd"><rect x="14" y="14" width="1172" height="1172" rx="28"/></clipPath><g clip-path="url(#cpd)">' + b + '</g>';
    pages.push({ id: 'deco-fans', title: 'Art Deco Fans', theme: 'Geometric', svg: wrap(b) });
  })();

  // 13 Succulent Bowl
  (function () {
    var b = '';
    b += path('M260 760 L940 760 Q900 1060 600 1080 Q300 1060 260 760 Z');
    b += path('M240 730 L960 730 L960 770 L240 770 Z');
    for (var i = 0; i < 5; i++) b += path('M' + (330 + i * 135) + ' 830 q30 40 0 80 q-30 -40 0 -80 Z');
    [[420, 560, 170, 9], [760, 580, 150, 8], [600, 470, 120, 7]].forEach(function (q) {
      b += ring(q[0], q[1], q[2] * 0.35, q[2], q[3], 0.28);
      b += ring(q[0], q[1], q[2] * 0.15, q[2] * 0.6, q[3], 0.32, 0.5);
      b += circle(q[0], q[1], q[2] * 0.15);
    });
    b += circle(980, 220, 90) + circle(980, 220, 60);
    pages.push({ id: 'succulent-bowl', title: 'Succulent Bowl', theme: 'Botanical', svg: wrap(b) });
  })();

  window.STILL_PAGES = pages;
})();
